    CreateEnvironmentMessage.add_member(:tier, Smithy::Schema::Shapes::ShapeRef.new(shape: EnvironmentTier, location_name: 'Tier', traits: {"smithy.api#documentation" => "<p>Specifies the tier to use in creating this environment. The environment tier that you\n      choose determines whether Elastic Beanstalk provisions resources to support a web application that handles\n      HTTP(S) requests or a web application that handles background-processing tasks.</p>"}))
